-- 격리된 로컬 PostgreSQL 전용 회귀. 모든 테스트 데이터는 마지막 ROLLBACK으로 되돌린다.
begin;
insert into auth.users(id) values('00000000-0000-0000-0000-000000000001'),('00000000-0000-0000-0000-000000000002'),('00000000-0000-0000-0000-000000000003');
insert into public.players(id) select id from auth.users on conflict do nothing;
insert into public.server_public_profiles(player_id,profile) select id,jsonb_build_object('id',id,'uid',uid::text,'displayName',case right(id::text,1) when '1' then 'Alice' when '2' then 'Bob' else 'Carol' end,'favoriteRelic',jsonb_build_object('relicId','torika')) from public.players;

do $$
declare a uuid:='00000000-0000-0000-0000-000000000001';b uuid:='00000000-0000-0000-0000-000000000002';c uuid:='00000000-0000-0000-0000-000000000003';r jsonb;first jsonb;v bigint;hp bigint;changes jsonb;definition jsonb;
begin
 if has_function_privilege('authenticated','public.server_social_call(uuid,text,jsonb,text)','execute') or has_table_privilege('authenticated','public.server_raids','select') then raise exception 'RLS/function exposure'; end if;
 r:=public.server_social_call(a,'sendRequest',jsonb_build_array(b),'request-social-1');
 if r->'result'->>'relation'<>'outgoing' then raise exception 'request not outgoing'; end if;
 if public.server_are_friends(a,b) then raise exception 'unaccepted friendship'; end if;
 r:=public.server_social_call(b,'getRequests','[]');
 if jsonb_array_length(r->'result'->'incoming')<>1 then raise exception 'recipient cannot see request'; end if;
 r:=public.server_social_call(b,'sendRequest',jsonb_build_array(a),'request-social-2');
 if not public.server_are_friends(a,b) then raise exception 'mutual request not accepted'; end if;
 r:=public.server_social_call(a,'getFriends','[]');
 if jsonb_array_length(r->'result'->'friends')<>1 then raise exception 'sender not friend'; end if;
 r:=public.server_social_call(b,'getFriends','[]');
 if jsonb_array_length(r->'result'->'friends')<>1 then raise exception 'recipient not friend'; end if;
 first:=public.server_social_call(a,'rentFavoriteRelic',jsonb_build_array(b),'request-rent-01');
 r:=public.server_social_call(a,'rentFavoriteRelic',jsonb_build_array(b),'request-rent-01');
 if r<>first or (select points from public.server_social_wallets where player_id=b)<>10 then raise exception 'double rental credit'; end if;
 perform public.server_social_call(a,'rentFavoriteRelic',jsonb_build_array(b),'request-rent-02');
 perform public.server_social_call(a,'rentFavoriteRelic',jsonb_build_array(b),'request-rent-03');
 begin perform public.server_social_call(a,'rentFavoriteRelic',jsonb_build_array(b),'request-rent-04');raise exception 'helper daily limit absent';exception when sqlstate 'PT422' then null; end;
 begin perform public.server_social_call(a,'sendRequest',jsonb_build_array(c),'request-social-1');raise exception 'request body binding absent';exception when sqlstate 'PT409' then null; end;
 if (select points from public.server_social_wallets where player_id=a)<>30 or (select points from public.server_social_wallets where player_id=b)<>30 then raise exception 'two-party point mismatch'; end if;
 perform public.server_social_call(a,'setFavorite',jsonb_build_array(b,true),'favorite-social-1');
 r:=public.server_social_call(a,'getFriends','[]');if jsonb_array_length(r->'result'->'favoriteIds')<>1 then raise exception 'favorite not persisted'; end if;
 r:=public.server_social_call(a,'searchUsers','[{"query":"Bob"}]');if jsonb_array_length(r->'result'->'users')<>1 then raise exception 'name search failed'; end if;
 begin perform public.server_social_call(a,'searchUsers','[{}]');raise exception 'invalid search accepted';exception when sqlstate 'PT400' then null; end;
 perform public.server_social_call(c,'sendRequest',jsonb_build_array(a),'request-extra-1');
 perform public.server_social_call(c,'cancelRequest',jsonb_build_array(a),'request-extra-2');
 perform public.server_social_call(c,'sendRequest',jsonb_build_array(a),'request-extra-3');
 perform public.server_social_call(a,'declineAllRequests','[]','request-extra-4');
 perform public.server_social_call(c,'sendRequest',jsonb_build_array(a),'request-extra-5');
 r:=public.server_social_call(a,'acceptAllRequests','[]','request-extra-6');if r->'result'->>'processed'<>'1' then raise exception 'bulk acceptance failed'; end if;
 perform public.server_social_call(a,'removeFriend',jsonb_build_array(c),'request-extra-7');
 perform public.server_social_call(c,'sendRequest',jsonb_build_array(a),'request-extra-8');
 perform public.server_social_call(a,'declineRequest',jsonb_build_array(c),'request-extra-9');
 r:=public.server_take_rate(a,'test',60,1); if not (r->>'allowed')::boolean then raise exception 'first rate rejected'; end if;
 r:=public.server_take_rate(a,'test',60,1); if (r->>'allowed')::boolean or (r->>'retryAfter')::int<1 then raise exception 'rate limit absent'; end if;
 r:=public.server_take_rate(b,'test',60,1); if not (r->>'allowed')::boolean then raise exception 'other account rate affected'; end if;
 definition:=jsonb_build_object('id','raid-test','kind','summon','bossRelicId','rex','difficulty','normal','openedAt',now(),'endsAt',now()+interval '1 day','myDamage',0,'appliedDamage',0,'attemptsUsed',0,'settled',false,'summonedByMe',true);
 changes:=jsonb_build_array(jsonb_build_object('instance',definition,'expectedRevision',null,'damageDelta',0,'appliedDelta',0,'attemptsDelta',0,'totalHp',100));
 perform public.server_commit_state(a,null,'{}','hash',1,jsonb_build_object('_raids',changes),'summonRaid','game-call-1','{}');
 r:=public.server_raid_context(b,'[]'); if jsonb_array_length(r->'records')<>1 then raise exception 'friend cannot see raid'; end if;
 r:=public.server_raid_context(c,'[]'); if jsonb_array_length(r->'records')<>0 then raise exception 'private summon leaked'; end if;
 select revision into v from public.server_raids where id='raid-test';
 changes:=jsonb_build_array(jsonb_build_object('instance',definition||jsonb_build_object('myDamage',40,'appliedDamage',40,'attemptsUsed',1,'summonedByMe',false),'expectedRevision',v::text,'damageDelta',40,'appliedDelta',40,'attemptsDelta',1,'totalHp',100));
 perform public.server_commit_state(b,null,'{}','hash',1,jsonb_build_object('_raids',changes),'submitRaidDamage','game-call-2','{}');
 select damage into hp from public.server_raids where id='raid-test';if hp<>40 then raise exception 'shared damage not applied'; end if;
 r:=public.server_raid_context(a,'[]');if r->'records'->0->>'damage'<>'40' or jsonb_array_length(r->'records'->0->'entries')<>1 then raise exception 'real participant missing'; end if;
 begin perform public.server_commit_state(a,1,'{}','hash',1,jsonb_build_object('_raids',changes),'submitRaidDamage','game-call-3','{}');raise exception 'stale shared revision accepted';exception when sqlstate 'PT409' then null; end;
 if (select damage from public.server_raids where id='raid-test')<>40 then raise exception 'failed commit changed shared HP'; end if;
 select revision into v from public.server_raids where id='raid-test';
 changes:=jsonb_build_array(jsonb_build_object('instance',definition||jsonb_build_object('myDamage',10,'appliedDamage',10,'attemptsUsed',1),'expectedRevision',v::text,'damageDelta',10,'appliedDelta',10,'attemptsDelta',1,'totalHp',100));
 begin perform public.server_commit_state(a,999,'{}','hash',1,jsonb_build_object('_raids',changes),'submitRaidDamage','game-call-4','{}');raise exception 'stale account revision accepted';exception when sqlstate 'PT409' then null; end;
 if (select damage from public.server_raids where id='raid-test')<>40 or exists(select 1 from public.server_raid_members where player_id=a and damage>0) then raise exception 'partial shared commit'; end if;
 perform public.server_social_call(a,'removeFriend',jsonb_build_array(b),'remove-friend-1');
 if public.server_are_friends(a,b) then raise exception 'friend removal not bilateral'; end if;
 update public.players set status='banned' where id=c;
 begin perform public.server_social_call(c,'getFriends','[]');raise exception 'blocked account passed';exception when sqlstate 'PT403' then null; end;
 raise notice 'PASS: two-account friendship/rental, idempotency, daily cap, rate budget, raid visibility/HP/participants, conflicts, rollback, RLS, blocked account';
end $$;
rollback;
